'use strict';
const Guide=RestorationGuide;
let guideSled='early',guideStepId='',guideErrors=[];
function guideState(){state.guides=Guide.migrate(state.guides);return state.guides;}
function guideRecord(sled,id){const record=guideState().sleds[sled].steps[id];if(record)return record;const data={};if(id==='evidence')Object.assign(data,sled==='early'?{overall:'photo-front',enginePhoto:'photo-motor'}:{overall:'photo-eight-porch',plateDisposition:'Plate / markings photographed',platePhoto:'photo-eight-plate'});if(id==='chassis'&&sled==='eight')Object.assign(data,{year:'1968',model:'Super Olympique E',code:'3E8-131356',conclusion:'Unresolved — more research needed'});if(id==='engine'&&sled==='early')Object.assign(data,{serial:'1308696',displacement:'247 cc on engine tag',photo:'photo-motor'});return{status:'draft',data,blocker:'',updated:''};}
function recordedChassis(sled){guideState();return Guide.isDone(Guide.steps.find(s=>s.id==='chassis'),state,sled)?guideRecord(sled,'chassis').data:null;}
function guideSledTitle(sled){const chassis=recordedChassis(sled);return chassis?chassis.year+' '+chassis.model:(sled==='early'?'1963? SKI-DOO':'1968 OLYMPIQUE 300 E');}
function guideIdentityCaption(sled){const chassis=recordedChassis(sled);return chassis?'Chassis identity recorded in the walkthrough':sled==='early'?'Early single-track · exact model unknown':'300 E · chassis code review open';}
function guideIdentityBadge(sled){return recordedChassis(sled)?'Identity recorded':sled==='early'?'Year unconfirmed':'Plate photographed';}
function guideProfileSpecs(sled){const chassis=recordedChassis(sled);return chassis?[['Recorded chassis year',chassis.year],['Recorded chassis model',chassis.model],['Chassis identifier',chassis.code],['Identity source',chassis.reference],['Supporting findings',chassis.reasoning],['Installed engine',guideRecord(sled,'engine').data.type||'Discovery still open']]:null;}
function guideSledPrompt(sled){guideState();const info=Guide.summary(state,sled),record=info.next?guideRecord(sled,info.next.id):null;return `<article class="guide-prompt"><div><span class="eyebrow">${esc(NAMES[sled])} / ${info.phase?esc(info.phase.title):'PROJECT CLOSED'}</span><h3>${info.next?esc(info.next.title):'Restoration record complete'}</h3><p>${record?.status==='blocked'?'Needs attention: '+esc(record.blocker):info.next?esc(info.next.summary):'All recorded stages are complete. Review or reopen a step whenever the findings change.'}</p><span class="guide-progress-caption">${info.done} / ${info.total} steps complete · ${info.percent}%</span></div><button class="button dark small" data-guide-sled="${sled}">${info.next?'Continue walkthrough':'Review walkthrough'} ↗</button></article>`}
function guideDashboard(){return `<section class="guided-home"><div class="section-head"><div><span class="eyebrow muted">YOUR NEXT ACTION</span><h2 style="margin-top:5px">Pick up where you left off.</h2></div><button data-nav="guide">Open guided restoration ↗</button></div><div class="guide-prompt-grid">${guideSledPrompt('early')}${guideSledPrompt('eight')}</div></section>`}
function guideNextOnBench(){return `<section class="panel"><div class="section-head"><h3>What’s holding up progress?</h3><span class="eyebrow muted">LIVE CHECKLIST</span></div>${['early','eight'].map((sled,i)=>{const info=Guide.summary(state,sled);return `<div class="task"><span class="num">0${i+1}</span><div><b>${esc(NAMES[sled])}</b><p>${info.next?esc(info.next.title):'All stages complete'}</p><button class="text-button" data-guide-sled="${sled}">Resolve the next step ↗</button></div></div>`}).join('')}<p class="mini-note">Later stages unlock when their required findings are recorded. Changing earlier evidence reopens affected stages.</p></section>`}
function guideField(field,data,sled){const value=data[field.id]??'',id='g-'+field.id;let control;if(field.type==='photo'){const photos=state.photos.filter(p=>p.sled===sled);control=`<select id="${id}" name="${field.id}" data-guide-field><option value="">Select the matching photo…</option>${photos.map(p=>option(p.id,p.title,value)).join('')}</select>${value&&photos.some(p=>p.id===value)?`<button type="button" class="guide-evidence" data-photo="${esc(value)}"><img src="${esc(photos.find(p=>p.id===value).src)}" alt="Selected evidence: ${esc(photos.find(p=>p.id===value).title)}">View selected evidence ↗</button>`:''}<button type="button" class="text-button" data-guide-upload="${sled}">+ Add another photo</button>`;}else if(field.type==='select'){control=`<select id="${id}" name="${field.id}" data-guide-field><option value="">Choose an answer…</option>${field.options.map(x=>option(x,x,value)).join('')}</select>`;}else if(field.type==='textarea'){control=`<textarea id="${id}" name="${field.id}" data-guide-field rows="3" maxlength="20000">${esc(value)}</textarea>`;}else if(field.type==='check'){control=`<label class="guide-check" for="${id}"><input id="${id}" type="checkbox" name="${field.id}" data-guide-field${value===true?' checked':''}><span>${esc(field.label)}</span></label>`;}else control=`<input id="${id}" name="${field.id}" data-guide-field type="${field.type}" value="${esc(value)}"${field.type==='number'?` min="${field.min}" max="${field.max}" step="1"`:''} maxlength="20000">`;return `<div class="field guide-field"${field.when?` data-guide-when="${esc(field.when[0])}" data-guide-equals="${esc(field.when[1])}"`:''}${Guide.visible(field,data)?'':' hidden'}>${field.type==='check'?'':`<label for="${id}">${esc(field.label)} <span class="required-mark">*</span></label>`}${control}</div>`;}
function guideParts(step,sled){let list;if(step.category)list=state.parts.filter(p=>p.sled===sled&&p.category===step.category);else if(['parts-plan','repairs'].includes(step.id))list=Guide.requiredParts(state,sled);else return'';return `<section class="guide-parts"><div class="section-head"><h4>Linked parts & work items</h4><button type="button" data-sled-parts="${sled}">Full tracker ↗</button></div>${list.length?list.map(p=>`<div class="guide-part-row"><div><b>${esc(p.name)}</b><small>${esc(p.status)} · ${p.number?esc(p.number):'Specification not recorded'}</small></div><button type="button" class="button secondary small" data-edit-part="${esc(p.id)}">Edit</button></div>`).join(''):'<p class="mini-note">No applicable items remain. Record why any items were retained or deferred in your findings.</p>'}</section>`;}
function guideStepStatus(step,sled){if(Guide.isDone(step,state,sled))return'Complete';if(Guide.blockers(step,state,sled).length)return'Locked';const record=guideRecord(sled,step.id);if(record.status==='blocked')return'Needs help';if(record.status==='complete')return'Recheck required';return record.updated?'In progress':'To do';}
function guideView(){guideState();const info=Guide.summary(state,guideSled);let step=Guide.steps.find(s=>s.id===guideStepId);if(!step)step=info.next||Guide.steps[0];guideStepId=step.id;const phase=Guide.phases.find(p=>p.id===step.phase),record=guideRecord(guideSled,step.id),blocked=Guide.blockers(step,state,guideSled),phaseSteps=Guide.steps.filter(s=>s.phase===phase.id),effective=Guide.isDone(step,state,guideSled),currentIssues=Guide.issues(step,record,state,guideSled);return `${head('GUIDED RESTORATION','One next step. Every time.','Capture the findings. Resolve the blockers. Move forward when the evidence is ready.')}<div class="pill-tabs"><button class="${guideSled==='early'?'active':''}" data-guide-sled="early">01 · Early Ski-Doo</button><button class="${guideSled==='eight'?'active':''}" data-guide-sled="eight">02 · 1968 Olympique</button></div><div class="guide-overall"><div><span class="eyebrow">${esc(NAMES[guideSled])}</span><h3>${info.phase?esc(info.phase.title)+' is in progress.':'Restoration record complete.'}</h3><p>${info.next?'Next: '+esc(info.next.title):'Review a stage below to inspect the record or reopen it.'}</p></div><div class="guide-meter"><strong>${info.percent}%</strong><span>${info.done} of ${info.total} steps</span><div class="progress"><i style="width:${info.percent}%"></i></div></div></div><div class="guide-layout"><aside class="guide-roadmap" aria-label="Restoration stages">${Guide.phases.map((p,i)=>{const members=Guide.steps.filter(s=>s.phase===p.id),done=members.filter(s=>Guide.isDone(s,state,guideSled)).length;const first=members.find(s=>!Guide.isDone(s,state,guideSled))||members[0],locked=Guide.blockers(first,state,guideSled).length>0;return `<button data-guide-step="${first.id}" class="guide-stage${p.id===phase.id?' selected':''}${done===members.length?' done':''}"${p.id===phase.id?' aria-current="step"':''}><span class="stage-num">${done===members.length?'✓':String(i+1).padStart(2,'0')}</span><span><b>${p.title}</b><small>${done}/${members.length} complete${locked?' · locked':''}</small></span></button>`}).join('')}<div class="guide-roadmap-note">A saved draft stays open. A completed step is checked again when evidence or part status changes.</div></aside><section class="guide-content"><div class="guide-step-list">${phaseSteps.map((s,i)=>`<button data-guide-step="${s.id}" class="${s.id===step.id?'selected':''}"><span>${Guide.isDone(s,state,guideSled)?'✓':String(i+1).padStart(2,'0')}</span><div><b>${esc(s.title)}</b><small>${guideStepStatus(s,guideSled)}</small></div></button>`).join('')}</div><article class="guide-workbench"><div class="section-head"><span class="eyebrow muted">${esc(phase.title)} / STEP ${phaseSteps.indexOf(step)+1} OF ${phaseSteps.length}</span><span class="badge ${effective?'green':'amber'}">${guideStepStatus(step,guideSled)}</span></div><h2>${esc(step.title)}</h2><p class="guide-summary">${esc(step.summary)}</p>${blocked.length?`<div class="banner"><b>This step is waiting on earlier findings.</b><p>Complete these requirements first. Your previous entries remain saved.</p><ul>${blocked.map(s=>`<li><button class="text-button" data-guide-step="${s.id}">${esc(s.title)} ↗</button></li>`).join('')}</ul></div>`:''}<ol class="guide-instructions">${step.instructions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="guide-reference-links"><button class="text-button" data-nav="archive">Open photos & factory references ↗</button><button class="text-button" data-guide-upload="${guideSled}">Add an evidence photo ↗</button></div>${record.status==='blocked'&&record.blocker?`<div class="banner"><b>Your open issue</b>${esc(record.blocker)}</div>`:''}${record.status==='complete'&&!effective&&!blocked.length?'<div class="banner"><b>This step needs another look.</b>A required field, photo or part status has changed. Resolve the current gaps and complete it again.</div>':''}<div id="guide-errors" role="alert" tabindex="-1">${guideErrorHTML(guideErrors)}</div><form id="guide-form" novalidate data-guide-id="${step.id}" data-guide-sled="${guideSled}"><fieldset${blocked.length?' disabled':''}>${step.fields.map(f=>guideField(f,record.data,guideSled)).join('')}${guideParts(step,guideSled)}<details class="guide-help"${record.status==='blocked'?' open':''}><summary>Stuck or missing information?</summary><div class="field"><label for="guide-blocker">What is blocking this step? What evidence or help do you need?</label><textarea id="guide-blocker" name="blocker" maxlength="10000" rows="3">${esc(record.blocker)}</textarea></div><button type="button" class="button secondary small" data-guide-action="blocked">Save issue & keep step open</button></details><div class="guide-form-actions"><button type="button" class="button secondary" data-guide-action="draft">Save draft</button><button type="submit" class="button dark">${effective?'Confirm & go to next step':'Complete step & continue'} →</button></div><p id="guide-save-state" class="mini-note">${record.updated?'Last saved '+esc(new Date(record.updated).toLocaleString()):'Known photo selections are prefilled. Review the evidence; no completion has been assumed.'}</p></fieldset></form>${!blocked.length?`<div class="guide-completion-note">${effective?'Recorded complete. Editing a finding reopens this step.':currentIssues.length+' completion requirement'+(currentIssues.length===1?'':'s')+' still open. Save partial findings any time.'}</div>`:''}</article></section></div>${mobileData()}`;}
function guideErrorHTML(errors){return errors.length?`<div class="guide-errors"><b>This step is still open.</b><ul>${errors.map(e=>`<li>${esc(e.message)}${e.part?` <button type="button" class="text-button" data-edit-part="${esc(e.part)}">Edit item ↗</button>`:e.step?` <button class="text-button" data-guide-step="${esc(e.step)}">Open step ↗</button>`:''}</li>`).join('')}</ul></div>`:'';}
function guideFormData(){const form=document.querySelector('#guide-form');if(!form)return null;const step=Guide.steps.find(s=>s.id===form.dataset.guideId);if(!step)return null;const values=new FormData(form),data={};for(const f of step.fields)data[f.id]=f.type==='check'?values.has(f.id):String(values.get(f.id)||'').trim();return{form,step,sled:form.dataset.guideSled,data,blocker:String(values.get('blocker')||'').trim()};}
function saveGuide(action='draft',silent=false){const found=guideFormData();if(!found)return false;const previous=JSON.stringify(state.guides),wasDone=Guide.isDone(found.step,state,found.sled);const result=Guide.save(state,found.sled,found.step.id,found.data,action,found.blocker);if(!result.ok){if(!silent){guideErrors=result.errors;const box=document.querySelector('#guide-errors');box.innerHTML=guideErrorHTML(guideErrors);box.focus();toast('The step is still open. Resolve the listed requirements.');}return false;}
 if(!persist()){state.guides=JSON.parse(previous);return false;}
 if(!silent){if(action==='complete'){state.logs.push({id:uid(),sled:found.sled,date:today(),title:'Guide: '+found.step.title,body:'Completed '+found.step.phase+' step.\n'+found.step.fields.filter(f=>Guide.visible(f,found.data)).map(f=>f.label+': '+(f.type==='photo'?(state.photos.find(p=>p.id===found.data[f.id])?.title||'Photo unavailable'):f.type==='check'?'Confirmed':found.data[f.id])).join('\n')});persist();guideStepId=result.next?.id||found.step.id;toast(result.next?'Step recorded. Here is your next action.':'All restoration stages are recorded complete.');}else toast(action==='blocked'?'Issue saved. This step will keep prompting you.':'Draft saved. This step remains open.');guideErrors=[];render('guide');}else{const status=document.querySelector('#guide-save-state');if(status)status.textContent=wasDone?'Changes saved as a draft. Complete the step again after reviewing.':'Draft saved in this browser. This step is still open.';}return true;}
function openGuide(sled,id=''){guideSled=['early','eight'].includes(sled)?sled:'early';guideState();guideStepId=id||Guide.summary(state,guideSled).next?.id||Guide.steps[0].id;guideErrors=[];navigate('guide');}
function guidePurchaseErrors(p,status){if(status!=='Ordered')return[];guideState();const gaps=Guide.steps.filter(s=>s.phase==='discovery'&&!Guide.isDone(s,state,p.sled));const errors=gaps.map(s=>'Complete '+s.title.toLowerCase()+'.');if(!String(p.number||'').trim())errors.push('Record a verified part number / measured service specification.');if(!safeURL(p.url))errors.push('Record the supplier or service reference link.');return errors;}
function showPurchaseGate(p,errors){toast('Order is not ready: '+errors[0]);openGuide(p.sled);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-guide-step')){guideStepId=b.dataset.guideStep;guideErrors=[];navigate('guide');return;}if(b.hasAttribute('data-guide-sled')){openGuide(b.dataset.guideSled);return;}if(b.hasAttribute('data-guide-upload')){guideSled=b.dataset.guideUpload;selectedSled=guideSled;openEditor('photo');const select=document.querySelector('#f-sled');if(select)select.value=guideSled;return;}if(b.dataset.guideAction)saveGuide(b.dataset.guideAction);});
document.addEventListener('submit',e=>{if(e.target.id==='guide-form'){e.preventDefault();saveGuide('complete');}});
function guideInput(e){if(!e.target.closest||!e.target.closest('#guide-form')||e.target.closest('fieldset')?.disabled)return;saveGuide('draft',true);if(e.target.matches('[data-guide-field]')){const data=guideFormData()?.data||{};document.querySelectorAll('[data-guide-when]').forEach(x=>x.hidden=data[x.dataset.guideWhen]!==x.dataset.guideEquals);if(e.type==='change'&&Guide.steps.find(s=>s.id===guideStepId)?.fields.some(f=>f.id===e.target.name&&f.type==='photo'))render('guide');}}
document.addEventListener('input',guideInput);document.addEventListener('change',guideInput);
